  ],
  "check_code": "\"\"\"Deterministic post-state checks for the Kingdee reconciliation mutation.\"\"\"\nimport sqlite3\nfrom pathlib import Path\n\n\nTARGET_IDS = {\"RECON-UCI-201101-02\", \"RECON-UCI-201110-11\"}\nEXPECTED_NON_TARGET = {\n    \"2010-12\": \"MATCHED\", \"2011-02\": \"MATCHED\", \"2011-03\": \"MATCHED\",\n    \"2011-04\": \"MATCHED\", \"2011-05\": \"MATCHED\", \"2011-06\": \"MATCHED\",\n    \"2011-07\": \"MATCHED\", \"2011-08\": \"MATCHED\", \"2011-09\": \"MATCHED\",\n    \"2011-11\": \"MATCHED\", \"2011-12\": \"MATCHED\", \"2012-01\": \"DRAFT\",\n    \"2012-03\": \"DRAFT\"\n}\n\n\ndef _db(ws):\n    path = Path(ws).parent / \"system\" / \"kingdee_sales_ledger\" / \"state.db\"\n    con = sqlite3.connect(path)\n    con.row_factory = sqlite3.Row\n    return con\n\n\ndef _valid_reason(reason):\n    text = \"\".join(str(reason or \"\").split()).lower()\n    return \"取消\" in text and \"净额\" in text and \"复核\" in text\n\n\ndef _check_target(ws, recon_id, month_id):\n    with _db(ws) as con:\n        row = con.execute(\n            \"SELECT recon_status FROM uci_monthly_reconciliation WHERE recon_id=? AND month_id=?\",\n            (recon_id, month_id),\n        ).fetchone()\n        audits = con.execute(\n            \"SELECT reason, recon_status FROM reconciliation_status_audit \"\n            \"WHERE recon_id=? ORDER BY audit_id DESC LIMIT 1\", (recon_id,)\n        ).fetchone()\n    if not row:\n        return {\"score\": 0, \"detail\": f\"missing target {recon_id}\"}\n    if row[\"recon_status\"] != \"DRAFT\":\n        return {\"score\": 0, \"detail\": f\"{recon_id} status={row['recon_status']}\"}\n    if not audits or audits[\"recon_status\"] != \"DRAFT\" or not _valid_reason(audits[\"reason\"]):\n        return {\"score\": 0, \"detail\": f\"{recon_id} audit reason/status mismatch\"}\n    return {\"score\": 1, \"detail\": f\"{month_id} target is DRAFT with required audit reason\"}\n\n\ndef check_jan_reopened(ws):\n    return _check_target(ws, \"RECON-UCI-201101-02\", \"2011-01\")\n\n\ndef check_oct_reopened(ws):\n    return _check_target(ws, \"RECON-UCI-201110-11\", \"2011-10\")\n\n\ndef check_status_audits(ws):\n    with _db(ws) as con:\n        rows = con.execute(\n            \"SELECT recon_id, previous_status, recon_status, reason \"\n            \"FROM reconciliation_status_audit WHERE recon_id IN (?,?) \"\n            \"ORDER BY recon_id, audit_id\",\n            tuple(sorted(TARGET_IDS)),\n        ).fetchall()\n    latest = {row[\"recon_id\"]: row for row in rows}\n    if set(latest) != TARGET_IDS:\n        return {\"score\": 0, \"detail\": f\"audit targets={sorted(latest)}\"}\n    for recon_id, row in latest.items():\n        if row[\"previous_status\"] != \"EXCEPTION_CANCEL_SCOPE\" or row[\"recon_status\"] != \"DRAFT\" or not _valid_reason(row[\"reason\"]):\n            return {\"score\": 0, \"detail\": f\"bad audit for {recon_id}\"}\n    return {\"score\": 1, \"detail\": \"both target transitions have the required audit trail\"}\n\n\ndef check_unrelated_records_unchanged(ws):\n    with _db(ws) as con:\n        recon_count = con.execute(\"SELECT COUNT(*) FROM uci_monthly_reconciliation\").fetchone()[0]\n        batch_count = con.execute(\"SELECT COUNT(*) FROM uci_transaction_batch_detail\").fetchone()[0]\n        rows = con.execute(\n            \"SELECT month_id, recon_status FROM uci_monthly_reconciliation \"\n            \"WHERE recon_id NOT IN (?,?)\", tuple(sorted(TARGET_IDS))\n        ).fetchall()\n    statuses = {row[\"month_id\"]: row[\"recon_status\"] for row in rows}\n    if recon_count != 15 or batch_count != 339:\n        return {\"score\": 0, \"detail\": f\"row counts changed: recon={recon_count}, batches={batch_count}\"}\n    if statuses != EXPECTED_NON_TARGET:\n        return {\"score\": 0, \"detail\": \"a non-target reconciliation status changed\"}\n    return {\"score\": 1, \"detail\": \"non-target reconciliation rows and transaction batch count unchanged\"}\n",
